#!/usr/bin/env python3
"""versus_oct28.py | freepracticesat.com | Oct 28, 2026
Adds four comparison posts (Bluebook, PrepScholar, Princeton Review, 1600.io),
their cards at the top of the blog page, and four sitemap entries.
Changes nothing unless blog/index.html and sitemap.xml look as expected.
Undo: python3 versus_oct28.py --undo"""
import sys,os,json,base64,zlib,hashlib,shutil
C=json.loads('{"files": {"blog/freepracticesat-vs-1600io.html": {"d": "", "h": "c37a80382ad261e89e25fcc91ee285ea7cab7b8384c722bbf738febc789c0442"}, "blog/freepracticesat-vs-bluebook.html": {"d": "", "h": "4f29b128722f90cd9b8a998d6765d1e54d5f8384165b5ccdad37163a0261588e"}, "blog/freepracticesat-vs-prepscholar.html": {"d": "", "h": "1c752ad4f27db7f1900d943ec194a5de5ccc8e2768275195db1559f66ac47148"}, "blog/freepracticesat-vs-princeton-review.html": {"d": "", "h": "1bf88616d6180e044dea02bbbb3e3e5aec3375c894981ddd0c3628c4e7fc2f39"}}, "hr": "<hr class=\\"gold-rule\\">\\n", "cards": "<a class=\\"post-card\\" href=\\"/blog/freepracticesat-vs-bluebook.html\\">\\n<p class=\\"meta\\">For Students &middot; October 28, 2026</p>\\n<h2>freepracticeSAT.com or Bluebook: How I Would Use Both for SAT Math</h2>\\n<p>Bluebook has the official practice tests, and there are only so many of them. How to spend them well, and what to use in between.</p>\\n</a>\\n<a class=\\"post-card\\" href=\\"/blog/freepracticesat-vs-prepscholar.html\\">\\n<p class=\\"meta\\">For Students &amp; Parents &middot; October 28, 2026</p>\\n<h2>freepracticeSAT.com vs PrepScholar: Two SAT Study Plans, $29 and $397</h2>\\n<p>Both build a study plan from your own results. One covers the whole SAT for a year, the other is math only and runs to your test date.</p>\\n</a>\\n<a class=\\"post-card\\" href=\\"/blog/freepracticesat-vs-princeton-review.html\\">\\n<p class=\\"meta\\">For Parents &middot; October 28, 2026</p>\\n<h2>freepracticeSAT.com or The Princeton Review for SAT Math?</h2>\\n<p>Princeton Review options run from a $299 course to tutoring at $315 an hour. What you get at each level, and when a free math site is enough.</p>\\n</a>\\n<a class=\\"post-card\\" href=\\"/blog/freepracticesat-vs-1600io.html\\">\\n<p class=\\"meta\\">For Students &middot; October 28, 2026</p>\\n<h2>freepracticeSAT.com vs 1600.io: Video Explanations or a Diagnosis?</h2>\\n<p>1600.io shows you how to solve official questions. My site tries to find out why you missed them. What each does well, and how to use both.</p>\\n</a>\\n", "smap": "  <url>\\n    <loc>https://freepracticesat.com/blog/freepracticesat-vs-bluebook.html</loc>\\n    <lastmod>2026-10-28</lastmod>\\n  </url>\\n  <url>\\n    <loc>https://freepracticesat.com/blog/freepracticesat-vs-prepscholar.html</loc>\\n    <lastmod>2026-10-28</lastmod>\\n  </url>\\n  <url>\\n    <loc>https://freepracticesat.com/blog/freepracticesat-vs-princeton-review.html</loc>\\n    <lastmod>2026-10-28</lastmod>\\n  </url>\\n  <url>\\n    <loc>https://freepracticesat.com/blog/freepracticesat-vs-1600io.html</loc>\\n    <lastmod>2026-10-28</lastmod>\\n  </url>\\n"}')
BK='.versus_backup_20261028'
EDIT=['blog/index.html','sitemap.xml']
sha=lambda b: hashlib.sha256(b).hexdigest()
rd=lambda p: open(p,'rb').read()
if '--undo' in sys.argv:
    if not os.path.isdir(BK): sys.exit('No backup found. Nothing undone.')
    for f in EDIT: shutil.copyfile(os.path.join(BK,f.replace('/','_')),f)
    for f in C['files']:
        if os.path.exists(f): os.rename(f,os.path.join(BK,'removed_'+f.replace('/','_')))
    print('UNDONE: blog page and sitemap restored, the four posts removed. Click Republish.'); sys.exit()
blog=rd('blog/index.html'); site=rd('sitemap.xml')
if all(os.path.exists(f) and sha(rd(f))==v['h'] for f,v in C['files'].items()) and C['cards'].encode() in blog:
    print('Already done. Nothing to change.'); sys.exit()
bad=[]
if blog.count(C['hr'].encode())!=1: bad.append('blog/index.html (the gold rule line was not found exactly once)')
if blog.count(b'<!DOCTYPE')!=1: bad.append('blog/index.html (not exactly one DOCTYPE)')
if site.count(b'</urlset>')!=1: bad.append('sitemap.xml (end tag)')
for f in C['files']:
    if os.path.exists(f): bad.append(f+' (already exists)')
    if f.encode() in blog: bad.append('blog/index.html already links '+f)
if bad:
    print('STOP. Nothing was changed:'); print('\n'.join(bad)); sys.exit(1)
os.makedirs(BK,exist_ok=True)
for f in EDIT: shutil.copyfile(f,os.path.join(BK,f.replace('/','_')))
for f,v in C['files'].items():
    b=zlib.decompress(base64.b64decode(v['d'])); assert sha(b)==v['h']
    open(f,'wb').write(b)
hr=C['hr'].encode()
open('blog/index.html','wb').write(blog.replace(hr,hr+C['cards'].encode(),1))
open('sitemap.xml','wb').write(site.replace(b'</urlset>',C['smap'].encode()+b'</urlset>',1))
b2=rd('blog/index.html'); s2=rd('sitemap.xml')
ok=all(sha(rd(f))==v['h'] for f,v in C['files'].items()) and b2.count(b'<!DOCTYPE')==1 and s2.count(b'<loc>')==site.count(b'<loc>')+4
print('DONE: four comparison posts added to the blog and sitemap. Click Republish.' if ok else 'CHECK FAILED. Run: python3 versus_oct28.py --undo')
